const input = $input.first().json;
const isRecord = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);

function findSubmission(value, depth = 0) {
  if (depth > 10) return null;
  if (isRecord(value)) {
    if (value.schemaVersion === 1 && typeof value.submissionId === 'string') return value;
    for (const child of Object.values(value)) {
      const found = findSubmission(child, depth + 1);
      if (found) return found;
    }
    return null;
  }
  if (Array.isArray(value)) {
    for (const child of value) {
      const found = findSubmission(child, depth + 1);
      if (found) return found;
    }
    return null;
  }
  if (typeof value !== 'string') return null;

  const candidates = [value.trim()];
  try {
    const decoded = decodeURIComponent(value.trim());
    if (!candidates.includes(decoded)) candidates.push(decoded);
  } catch {}
  for (const candidate of candidates) {
    try {
      const parsed = JSON.parse(candidate);
      const found = findSubmission(parsed, depth + 1);
      if (found) return found;
    } catch {}
  }
  return null;
}

const submission = findSubmission(input);
if (!submission) {
  const body = isRecord(input) ? input.body : undefined;
  const bodyInfo = typeof body === 'string' ? `string (${body.length} chars)` : typeof body;
  throw new Error(`El body no contiene JSON SIFCO válido; se recibió ${bodyInfo}. Enviar JSON directo en body.`);
}
if (typeof submission.submissionId !== 'string' || !submission.submissionId.trim()) {
  throw new Error('Falta submissionId');
}
if (typeof submission.submittedAt !== 'string' || Number.isNaN(Date.parse(submission.submittedAt))) {
  throw new Error('submittedAt no es una fecha válida');
}
const channel = submission.channel === 'meta' ? 'meta' : 'directo';
if (!isRecord(submission.contact) || typeof submission.contact.email !== 'string') {
  throw new Error('Falta el correo de contacto');
}
// El tráfico META se salta el formulario de contacto, por lo que llega sin correo.
if (channel !== 'meta' && !submission.contact.email.trim()) {
  throw new Error('Falta el correo de contacto');
}
if (!isRecord(submission.answers) || !isRecord(submission.results)) {
  throw new Error('Faltan answers o results');
}

const answerKeys = [
  'solicitudesMes', 'porcentajeAprobado', 'montoTicket', 'tiempoAprobacion', 'tiempoDesembolso',
  'numAnalistas', 'salarioAnalista', 'horasLaboralesMes', 'porcentajeAbandono', 'porcentajeReprocesos',
  'porcentajeManual', 'sistemasActuales', 'saldoCarteraActiva', 'porcentajeMoraNPL', 'diasAtrasoPromedio',
  'porcentajeRecuperacion', 'costoMensualCobranza', 'porcentajeGestionesManuales',
  'porcentajePagosManuales', 'porcentajeErroresAplicacion', 'porcentajeWriteOffAnual'
];
for (const key of answerKeys) {
  if (typeof submission.answers[key] !== 'number' || !Number.isFinite(submission.answers[key])) {
    throw new Error(`La respuesta ${key} debe ser numérica`);
  }
}

const resultKeys = [
  'CREDITOS_MES', 'T_TOTAL', 'COSTO_HORA', 'HRS_X_CREDITO', 'COSTO_X_CREDITO',
  'PERDIDA_ABANDONO', 'COSTO_REPROCESOS', 'CAP_NUEVA', 'CRED_ADD', 'COSTO_NUEVO',
  'DIAS_AHORRADOS', 'indicadorEficiencia', 'indicadorRiesgoOp', 'indicadorAutomatizacion',
  'ROI_COLOCACION', 'CARTERA_MORA', 'PERDIDA_MORA', 'COSTO_ERROR_PAG', 'CASTIGO_MENS',
  'TASA_REC_NEW', 'MORA_PCT_NEW', 'CARTERA_MORA_NEW', 'PERDIDA_MORA_NEW', 'COSTO_COB_NEW',
  'COSTO_ERROR_NEW', 'indicadorMora', 'indicadorEficienciaCob', 'indicadorRiesgoPagos',
  'AHORRO_MORA', 'AHORRO_COB', 'AHORRO_ERR', 'ROI_RECUPERACION', 'ROI_TOTAL'
];
const indicatorKeys = new Set([
  'indicadorEficiencia', 'indicadorRiesgoOp', 'indicadorAutomatizacion',
  'indicadorMora', 'indicadorEficienciaCob', 'indicadorRiesgoPagos'
]);
for (const key of resultKeys) {
  const value = submission.results[key];
  const valid = indicatorKeys.has(key)
    ? typeof value === 'string'
    : typeof value === 'number' && Number.isFinite(value);
  if (!valid) throw new Error(`El resultado ${key} tiene un formato inválido`);
}

const text = (value) => typeof value === 'string' ? value.trim() : '';
const row = {
  schemaVersion: submission.schemaVersion,
  submissionId: submission.submissionId.trim(),
  submittedAt: submission.submittedAt,
  receivedAt: new Date().toISOString(),
  source: text(submission.source) || 'sifco-roi-calculator',
  channel,
  contact_firstName: text(submission.contact.firstName),
  contact_lastName: text(submission.contact.lastName),
  contact_email: text(submission.contact.email),
  contact_contactPreference: text(submission.contact.contactPreference),
  contact_areaCode: text(submission.contact.areaCode),
  contact_phone: text(submission.contact.phone),
  contact_implementationDeadline: text(submission.contact.implementationDeadline),
  contact_marketingConsent: submission.contact.marketingConsent === true
};
for (const key of answerKeys) row[`answer_${key}`] = submission.answers[key];
for (const key of resultKeys) row[`result_${key}`] = submission.results[key];

return [{ json: row }];

